import React from "react";
import { View, FlatList, ImageBackground, Linking } from "react-native";
import { StyleService, useStyleSheet } from "@ui-kitten/components";
import useLayout from "hooks/useLayout";

import Text from "components/Text";
import NavigationAction from "components/NavigationAction";
import Images from "assets/images";
import { HStack, VStack } from "components";
import Banner from "components/Banner";
interface Props {
  index: number;
}
const Projects = ({ index }: Props) => {
  const { width } = useLayout();
  const styles = useStyleSheet(themedStyles);
  const wItem = (width - 63) / 2;

  const Item = React.useCallback(({ item }) => {
    return (
      <View style={styles.item}>
        <ImageBackground
          source={item.image}
          /* @ts-ignore */
          imageStyle={styles.imgStyle}
          style={{ width: wItem, height: wItem, alignItems: "flex-end" }}
        >
          <NavigationAction icon="heart" />
        </ImageBackground>
        <Text
          children={item.title}
          marginTop={12}
          marginBottom={4}
          category="callout"
        />
        <Text
          children={`${item.liked} Likes`}
          category="subhead"
          status="snow"
        />
      </View>
    );
  }, []);
  return (
    <FlatList
      numColumns={2}
      data={DATA}
      style={styles.flatList}
      keyExtractor={(i, _) => i.id.toString()}
      ListHeaderComponent={() => (
        <VStack>
          <HStack>
            <Item item={DATA[0]} />
            <Item item={DATA[1]} />
          </HStack>
          <VStack
            mb={24}
            onPress={() => Linking.openURL("https://www.okx.com/join/45798910")}
          >
            <Banner.Crypto />
          </VStack>
        </VStack>
      )}
      renderItem={({ item, index }) => {
        if (index === 0 || index === 1) {
          return null;
        }
        return <Item item={item} />;
      }}
    />
  );
};

export default Projects;

const themedStyles = StyleService.create({
  container: {
    flex: 1,
  },
  item: {
    marginRight: 15,
    marginBottom: 24,
  },
  flatList: {
    marginHorizontal: 24,
    marginTop: 16,
  },
  imgStyle: {
    borderRadius: 12,
  },
});
