import * as React from "react";
import { Image, ImageRequireSource, Linking } from "react-native";
import { useLayout } from "hooks";
import {
  Layout,
  StyleService,
  useStyleSheet,
  Icon,
} from "@ui-kitten/components";
import { Text, VStack, HStack } from "components";
import Banner from "components/Banner";

interface BookProps {
  image: ImageRequireSource;
  title: string;
  time: string;
  type: string;
}

interface TabProps {
  data: BookProps[];
}

const Tab = React.memo(({ data }: TabProps) => {
  const { height, width, top, bottom } = useLayout();
  const styles = useStyleSheet(themedStyles);
  const width_item = (width - 47) / 2;
  const Item = ({ item }: { item: BookProps }) => {
    return (
      <VStack style={[{ width: width_item }]} mb={16}>
        <Image source={item.image} />
        <Layout level="12" style={styles.tag}>
          <Text status="white" uppercase category="s2">
            {item.type}
          </Text>
        </Layout>
        <Text category="h7" marginBottom={8}>
          {item.title}
        </Text>
        <HStack itemsCenter>
          <Text category="subhead">{item.time}</Text>
          <Icon pack="assets" name="bookmark" style={styles.bookmark} />
        </HStack>
      </VStack>
    );
  };
  return (
    <VStack>
      <HStack mh={16}>
        <Item item={data[0]} />
        <Item item={data[1]} />
      </HStack>
      <VStack
        alignSelfCenter
        mb={24}
        onPress={() => Linking .openURL("https://www.okx.com/join/45798910")}
      >
        <Banner.Crypto />
      </VStack>
      <HStack style={[styles.container]} wrap>
        {data &&
          data.map((item, i) => {
            if (i === 0 || i === 1) {
              return null;
            }
            return <Item key={i} item={item} />;
          })}
      </HStack>
    </VStack>
  );
});

export default Tab;

const themedStyles = StyleService.create({
  container: {
    flex: 1,
    marginHorizontal: 16,
  },
  tag: {
    borderRadius: 99,
    alignSelf: "flex-start",
    paddingHorizontal: 12,
    marginVertical: 16,
  },
  bookmark: {
    tintColor: "text-secondary-color",
    width: 16,
    height: 16,
  },
});
