import React, { memo } from "react";
import { View, Image } from "react-native";
import { useTheme, StyleService, useStyleSheet } from "@ui-kitten/components";
import { useNavigation } from "@react-navigation/native";
import { useLayout } from "hooks";
import { useAudioPlayer } from "expo-audio";
import {
  Container,
  Content,
  HStack,
  IDivider,
  NavigationAction,
  Text,
} from "components";
import Images from "assets/images";
import CustomSlider from "./CustomSlider";
import CustomController from "./CustomController";
import BookItem from "./BookItem";

const Reading05 = memo(() => {
  const { goBack } = useNavigation();
  const { height, width, top, bottom } = useLayout();
  const theme = useTheme();
  const styles = useStyleSheet(themedStyles);
  const [id, setId] = React.useState(0);

  const player = useAudioPlayer(track[0].uri);
  const [isPlay, setIsPlay] = React.useState(false);

  const PlayAudio = React.useCallback(() => {
    if (player.playing) {
      player.pause();
      setIsPlay(false);
    } else {
      player.play();
      setIsPlay(true);
    }
  }, [player]);

  const pressRedo = React.useCallback(() => {
    const newTime = Math.min(player.currentTime + 10, player.duration);
    player.currentTime = newTime;
  }, [player]);

  const pressUndo = React.useCallback(() => {
    const newTime = Math.max(player.currentTime - 10, 0);
    player.currentTime = newTime;
  }, [player]);
  return (
    <Container style={styles.container}>
      <HStack style={[styles.header, { top: top + 8 }]}>
        <NavigationAction status="primary" />
        <NavigationAction status="primary" icon="circles_four" />
      </HStack>
      <Content
        contentContainerStyle={[styles.content, { paddingBottom: bottom + 24 }]}
      >
        <Image
          source={track[id].image}
          /* @ts-ignore */
          style={styles.book}
        />
        <Text center category="c1" marginTop={32}>
          {track[id].title}
        </Text>
        <Text center category="body" marginTop={8} capitalize>
          {track[id].author}
        </Text>
        <CustomSlider
          value={player.currentTime * 1000}
          maxValue={player.duration * 1000}
          onSlidingStart={() => {
            setIsPlay(false);
            player.pause();
          }}
          onValueChange={(value) => {
            const newTime = Array.isArray(value) ? value[0] : value;
            player.currentTime = newTime / 1000;
          }}
          onSlidingComplete={(value) => {
            const newTime = Array.isArray(value) ? value[0] : value;
            player.currentTime = newTime / 1000;
            player.play();
            setIsPlay(true);
          }}
        />

        <CustomController
          pressPlayPause={PlayAudio}
          playPause={isPlay}
          loading={false}
          pressRedo={pressRedo}
          pressUndo={pressUndo}
        />

        <View style={styles.timeSleep}>
          <Text category="body" status="snow">
            Time Sleep
          </Text>
          <Text category="h7">1 Hour</Text>
        </View>
        <IDivider marginBottom={24} />
        <BookItem
          image={track[1].image}
          title={track[1].title}
          author={track[1].author}
        />
      </Content>
    </Container>
  );
});

export default Reading05;

const themedStyles = StyleService.create({
  container: {
    flex: 1,
    paddingBottom: 0,
  },
  header: {
    position: "absolute",
    left: 0,
    right: 0,
    zIndex: 100,
  },
  content: {
    paddingHorizontal: 24,
    paddingTop: 40,
  },
  book: {
    alignSelf: "center",
  },
  timeSleep: {
    flexDirection: "row",
    justifyContent: "space-between",
    marginBottom: 14,
  },
});
const track = [
  {
    id: 0,
    image: Images.reading.reading04,
    title: "The world, your life",
    author: "june cook",
    uri: "https://res.cloudinary.com/whisky131/video/upload/v1634101632/Not_Afraid_tndelo.mp3",
  },
  {
    id: 1,
    image: Images.reading.reading05,
    title: "The world,your life",
    author: "june cook",
    uri: "https://res.cloudinary.com/whisky131/video/upload/v1634101632/Not_Afraid_tndelo.mp3",
  },
];
