import * as React from "react";
import { View, TouchableHighlight, Linking } from "react-native";
import { useLayout } from "hooks";
import {
  Layout,
  StyleService,
  useStyleSheet,
  Button,
  Icon,
} from "@ui-kitten/components";
import { VideoView, useVideoPlayer } from "expo-video";
import { Container, Content, Text, NavigationAction, VStack } from "components";
import CustomSlider from "./CustomSlider";
import Images from "assets/images";
import WorkoutItem from "../Fitness06/WorkoutItem";
import Banner from "components/Banner";

const VIDEO = {
  uri: "https://res.cloudinary.com/whisky131/video/upload/v1633324283/gym_ml8gjg.mp4",
};
const Fitness07 = React.memo(() => {
  const { height, width, top, bottom } = useLayout();
  const styles = useStyleSheet(themedStyles);

  const player = useVideoPlayer(VIDEO.uri, (player) => {
    player.loop = false;
    player.volume = 0.5;
    player.play();
  });

  const [time, setTime] = React.useState("");
  const [minutes, setMinutes] = React.useState(0);
  const [second, setSecond] = React.useState("");
  const [duration, setDuration] = React.useState(0);
  const [currentTime, setCurrentTime] = React.useState(0);
  const [showPlayPause, setShowPlayPause] = React.useState(false);
  const [playPause, setPlayPause] = React.useState(false);

  React.useEffect(() => {
    const interval = setInterval(() => {
      setDuration(player.currentTime * 1000);
      setCurrentTime(player.duration * 1000);
    }, 500);

    return () => clearInterval(interval);
  }, [player]);

  React.useEffect(() => {
    let timer1 = setTimeout(() => {
      if (showPlayPause === true) {
        setShowPlayPause(false);
      }
      return () => {
        clearTimeout(timer1);
      };
    }, 5.8 * 1000);
  }, [showPlayPause]);

  React.useEffect(() => {
    let y = duration - (duration % 60000);
    let x = Math.floor(y / 60000);
    let z = (duration % 60000) / 1000;
    setMinutes(x);
    setSecond(z.toFixed(0));
    return setTime(
      `${minutes >= 10 ? `${minutes.toFixed(0)}` : `0${minutes}`}:${
        (duration % 60000) / 1000 <= 10 ? "0" : ""
      }${second}`
    );
  }, [duration, second, minutes]);

  const PauseAndPlay = React.useCallback(() => {
    if (player.playing) {
      player.pause();
      setPlayPause(true);
    } else {
      player.play();
      setPlayPause(false);
    }
  }, [player]);
  return (
    <Container style={styles.container} useSafeArea={false}>
      <NavigationAction
        style={[styles.goBack, { top: top + 8 }]}
        status="transparent"
      />
      <TouchableHighlight onPress={() => setShowPlayPause(!showPlayPause)}>
        <View>
          <View>
            {showPlayPause ? (
              <Layout
                level="2"
                style={[
                  {
                    width: width,
                    height: height / 1.85,
                    marginTop: -((width * 1.25) / 6.5),
                  },
                  styles.playPause,
                ]}
              >
                <Button
                  onPress={PauseAndPlay}
                  accessoryRight={
                    <Icon pack="assets" name={playPause ? "play" : "pause"} />
                  }
                />
              </Layout>
            ) : null}
          </View>
          <VideoView
            player={player}
            style={{
              width: width,
              height: 364 * (height / 812),
              zIndex: -10,
            }}
            contentFit="cover"
            nativeControls={false}
          />
        </View>
      </TouchableHighlight>
      <CustomSlider
        value={duration}
        maxValue={currentTime}
        time={time}
        style={{ marginTop: -width / 8.5 }}
      />
      <Content style={{ marginTop: width / 15, ...styles.content }}>
        {DATA.map((item, index) => {
          if (!item) {
            return (
              <VStack
                key={"ad"}
                mt={16}
                alignSelfCenter
                onPress={() =>
                  Linking.openURL("https://www.okx.com/join/45798910")
                }
              >
                <Banner.Crypto />
              </VStack>
            );
          }
          return <WorkoutItem data={item} key={index} />;
        })}
      </Content>
    </Container>
  );
});

export default Fitness07;

const themedStyles = StyleService.create({
  container: {
    flex: 1,
    paddingBottom: 0,
  },
  playPause: {
    opacity: 0.8,
    position: "absolute",
    alignItems: "center",
    justifyContent: "center",
    top: 0,
    right: 0,
    left: 0,
  },
  goBack: {
    position: "absolute",
    zIndex: 100,
    left: 16,
  },
  content: {
    paddingHorizontal: 24,
    paddingBottom: 60,
  },
});
const DATA = [
  {
    id: 0,
    title: "Begin Assessment",
    times: 20,
    rep: 3,
    image: Images.fitness.workout05,
  },
  {
    id: 1,
    title: "Begin Assessment",
    times: 20,
    rep: 3,
    image: Images.fitness.workout06,
  },
  undefined,
  {
    id: 2,
    title: "Begin Assessment",
    times: 20,
    rep: 3,
    image: Images.fitness.workout07,
  },
  {
    id: 3,
    title: "Begin Assessment",
    times: 20,
    rep: 3,
    image: Images.fitness.workout08,
  },
];
